def find_orfs(s, label):
    out=[]
    for f in range(3):
        # split frame into codons
        codons=[s[i:i+3] for i in range(f, len(s)-2, 3)]
        # find runs between stops
        i=0
        for idx,c in enumerate(codons):
            if c in STOPS:
                pass
        # simpler: walk
        pos=f
        start_run=None
        for idx,c in enumerate(codons):
            gstart = f+idx*3
            if c in STOPS:
                if start_run is not None:
                    out.append((start_run, gstart, (gstart-start_run)//3, label, f))
                    start_run=None
            else:
                if start_run is None:
                    start_run=gstart
        if start_run is not None:
            out.append((start_run, f+len(codons)*3, (f+len(codons)*3-start_run)//3, label, f))
    return out

