STOPS={"TAA","TAG","TGA"}

def stopfree(s):
    for f in range(3):
        idx=0
        cur=None
        for idx in range(f, len(s)-2, 3):
            c=s[idx:idx+3]
            if c in STOPS:
                if cur is not None:
                    yield cur, idx
                    cur=None
            else:
                if cur is None: cur=idx
        if cur is not None:
            yield cur, len(s)

def report(s,label):
    for st,en in stopfree(s):
        if (en-st)>=150:
            # find first ATG in frame
            atg=None
            for a in range(st,en-2,3):
                if s[a:a+3]=="ATG": atg=a; break
            print(label, "ORF", st, en, "len_bp", en-st, "aa", (en-st)//3, "first ATG at", atg)

report(seq,"+")
report(rcseq,"-")

